import java.util.List;
import java.util.Optional;
import org.springframework.stereotype.Service;

@Service
public class UserService {
    private final UserRepository repository;
    public UserService(UserRepository repository) { this.repository = repository; }

    public UserRecord create(UserRecord item) { item.setId(null); return repository.save(item); }
    public List<UserRecord> list() { return repository.findAll(); }
    public Optional<UserRecord> find(Long id) { return repository.findById(id); }
    public Optional<UserRecord> update(Long id, UserRecord item) {
        return repository.findById(id).map(existing -> { existing.setName(item.getName()); return repository.save(existing); });
