    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
}

package com.example.myproject.order;

import org.springframework.data.jpa.repository.JpaRepository;
public interface OrderRepository extends JpaRepository<OrderRecord, Long> {}

package com.example.myproject.order;

import java.util.List;
import java.util.Optional;
import org.springframework.stereotype.Service;

@Service
public class OrderService {
    private final OrderRepository repository;
    public OrderService(OrderRepository repository) { this.repository = repository; }

    public OrderRecord create(OrderRecord item) { item.setId(null); return repository.save(item); }
    public List<OrderRecord> list() { return repository.findAll(); }
    public Optional<OrderRecord> find(Long id) { return repository.findById(id); }
    public Optional<OrderRecord> update(Long id, OrderRecord item) {
        return repository.findById(id).map(existing -> { existing.setName(item.getName()); return repository.save(existing); });
    }
    public boolean delete(Long id) {
        if (!repository.existsById(id)) return false;
        repository.deleteById(id); return true;
    }
}

package com.example.myproject.order;

import java.util.List;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService service;
    public OrderController(OrderService service) { this.service = service; }
    @GetMapping public List<OrderRecord> list() { return service.list(); }
    @GetMapping("/{id}") public ResponseEntity<OrderRecord> find(@PathVariable Long id) {
        return service.find(id).map(ResponseEntity::ok).orElseGet(() -> ResponseEntity.notFound().build());
    }
    @PostMapping public OrderRecord create(@RequestBody OrderRecord item) { return service.create(item); }
    @PutMapping("/{id}") public ResponseEntity<OrderRecord> update(@PathVariable Long id, @RequestBody OrderRecord item) {
        return service.update(id, item).map(ResponseEntity::ok).orElseGet(() -> ResponseEntity.notFound().build());
    }
    @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id) {
        return service.delete(id) ? ResponseEntity.noContent().build() : ResponseEntity.notFound().build();
    }
}

